#!/usr/bin/env bash
# Adds a general "Fix package" button to the release detail page for any
# package that failed validation. It synthesizes a missing update.json
# (this package's own version + supported_os copied from the most
# recently validated release) and copies rescue/*.py from that same donor
# release, then re-validates. This is a structural fix only — it makes an
# incomplete archive pass validate_update_zip's checks; it does NOT (and
# can't) confirm the archive's actual payload is the right one.
#
# NOTE ON v1.1.2 / v1.0.2: both currently-invalid packages in this repo
# contain admin_panel.db, install.ps1, config.py etc. at the archive root
# - that's the shape of a full server backup/checkout, not the release
# payload shape used by the validated v1.0.0/v1.0.1 packages (run.py,
# app/, requirements.txt at the root). Fix will happily make either one
# "validated", but pushing either to a live kiosk would deploy your
# actual admin_panel.db (and everything else in that backup) to the
# instance. Worth deleting/withdrawing those two rather than fixing them,
# unless a backup zip genuinely is what you meant to release.
#
# Adds:
#   - app/update_validation.py::repair_package()
#   - app/blueprints/releases.py: fix_package route + donor lookup
#   - app/templates/releases/detail.html: "Fix package" button
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in run.py app requirements.txt; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS"
cp app/update_validation.py "backups/$TS/update_validation.py.bak" 2>/dev/null || true
cp app/blueprints/releases.py "backups/$TS/releases.py.bak" 2>/dev/null || true
cp app/templates/releases/detail.html "backups/$TS/detail.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/update_validation.py"
base64 -d > app/update_validation.py << 'UPDATE_VALIDATION_PY_B64'

UPDATE_VALIDATION_PY_B64

echo "==> Writing app/blueprints/releases.py"
base64 -d > app/blueprints/releases.py << 'RELEASES_PY_B64'

RELEASES_PY_B64

echo "==> Writing app/templates/releases/detail.html"
base64 -d > app/templates/releases/detail.html << 'DETAIL_HTML_B64'

DETAIL_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/update_validation.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/releases.py').read())"
echo "    syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Fixed: invalid packages now show a 'Fix package' button that adds a"
echo "manifest + rescue/ component (copied from the latest validated"
echo "release) and re-validates."
echo ""
echo "v1.1.2 and v1.0.2 both look like full server backups, not release"
echo "payloads - see the note at the top of this script before using Fix"
echo "on either of them."
echo "==================================================================="
